        public void Bind(RestoredLobbyController owner, int index, GearRow row, Sprite icon, bool selected, bool weapon, int gearLevel, float value)
        {
            _owner = owner;
            _index = index;
            title.text = row.name;
            level.text = gearLevel.ToString();
            stat.text = value.ToString("0");
            if (statName != null)
            {
                statName.text = weapon ? "Damage" : "HP";
            }
            if (legendaryEffect != null)
            {
                legendaryEffect.SetActive(row.rarity == 4);
            }
            // 배열은 현재 카탈로그의 0 이상 희귀도·브랜드 값으로 구성한다.
            if (frame != null && rarityFrames != null && row.rarity >= 0 && row.rarity < rarityFrames.Length)
            {
                frame.sprite = rarityFrames[row.rarity];
            }
            // 원작 무기 제목은 무기군 아이콘을 쓰며, 방어구 제목에만 브랜드를 표시한다.
            var titleIcons = weapon ? weaponTitleIcons : brandIcons;
            int titleIndex = weapon ? row.family : row.brand;
            if (brand != null)
            {
                brand.sprite = titleIcons != null && titleIndex >= 0 && titleIndex < titleIcons.Length ? titleIcons[titleIndex] : null;
                brand.enabled = brand.sprite != null;
            }
            thumbnail.sprite = icon;
            thumbnail.enabled = icon != null;
            selectedMark.SetActive(selected);
        }
